/**
 * Keep the vendored third-party skills honest about where they came from.
 *
 * `assets/skills/` has one source: a pinned git submodule, regenerated by
 * `sync-upstream.ts`. The extension tree does not have that luxury. It groups skills
 * by upstream repository (`skills-ext/<source>/<skill>/`), each source moves on
 * its own schedule, and nothing in the repository is a git remote for them. So the
 * pin lives in `scripts/skills-ext/sources.yml` and this script is what makes it mean
 * something.
 *
 * Three failure modes it exists to catch, in the order they cost the most:
 *
 * 1. **Local edit drift.** Someone fixes a sentence in a vendored file and forgets
 *    that the next refresh overwrites it. `--check` compares content hashes against
 *    what the pin recorded, so an edited copy fails loudly.
 * 2. **Silent upstream divergence.** The upstream repository changed the skill. No
 *    local check can see that without the network, so `--check --remote` re-fetches
 *    the pinned revision and reports which files differ. Reporting is the whole
 *    contract: adopting an upstream change is a review decision, not a sync step.
 * 3. **Unrecorded local files.** A file added to a vendored skill directory without a
 *    provenance entry would ship with no record of where it came from. Both directions
 *    of the file list are checked.
 *
 * The hashes are stored in the manifest rather than recomputed from the network on
 * every run, because `pnpm run check` must pass offline. `--write` refreshes them
 * after an intentional update.
 */
import { createHash } from "node:crypto";
import { existsSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { join, relative } from "node:path";

import yaml from "js-yaml";

import { ROOT } from "./root.ts";

/** Where the pinned sources and their file hashes live. */
export const SOURCES_PATH = join(ROOT, "scripts", "skills-ext", "sources.yml");

/** Where the vendored skill trees live, one directory per source id. */
export const SKILLS_EXT_ROOT = join(ROOT, "skills-ext");

/** One vendored skill inside a source. */
export interface VendoredSkill {
  readonly name: string;
  /** Path of the skill directory inside the upstream repository. */
  readonly upstream: string;
  /** Upstream-relative file paths that ship. */
  readonly files: readonly string[];
  /** Lower-case hex SHA-256 of each shipped file, keyed by its relative path. */
  readonly hashes?: Readonly<Record<string, string>>;
  readonly note?: string;
}

/** One upstream repository and the skills vendored from it. */
export interface VendoredSource {
  readonly id: string;
  readonly repository: string;
  readonly license: string;
  readonly copyright: string;
  /** Commit SHA the copy was taken from. A branch name is not a pin. */
  readonly revision: string;
  readonly branch?: string;
  readonly fetched?: string;
  readonly skills: readonly VendoredSkill[];
}

export interface SourcesFile {
  readonly sources: readonly VendoredSource[];
}

export function readSources(path: string = SOURCES_PATH): SourcesFile {
  const parsed = yaml.load(readFileSync(path, "utf8"));
  if (typeof parsed !== "object" || parsed === null || !Array.isArray((parsed as SourcesFile).sources)) {
    throw new Error(`${relative(ROOT, path)}: expected a top-level \`sources\` list`);
  }
  return parsed as SourcesFile;
}

/** Directory of one vendored skill inside this repository. */
export function skillDirectory(source: VendoredSource, skill: VendoredSkill): string {
  return join(SKILLS_EXT_ROOT, source.id, skill.name);
}

/** SHA-256 of one file's bytes, or `undefined` when it is absent. */
export function hashFile(path: string): string | undefined {
  if (!existsSync(path)) return undefined;
  return createHash("sha256").update(readFileSync(path)).digest("hex");
}

/** Hash every listed file of one vendored skill, skipping the ones that are absent. */
export function hashSkill(source: VendoredSource, skill: VendoredSkill): Record<string, string> {
  const directory = skillDirectory(source, skill);
  const hashes: Record<string, string> = {};
  for (const file of skill.files) {
    const hash = hashFile(join(directory, ...file.split("/")));
    if (hash !== undefined) hashes[file] = hash;
  }
  return hashes;
}

/**
 * Compare the tree on disk with what the manifest recorded.
 *
 * Pure except for reading files, so the checks are unit-testable without network.
 */
export function checkLocalTree(sources: SourcesFile): readonly string[] {
  const problems: string[] = [];

  for (const source of sources.sources) {
    const sourceRoot = join(SKILLS_EXT_ROOT, source.id);
    if (source.skills.length === 0) continue;
    if (!existsSync(sourceRoot)) {
      problems.push(`skills-ext/${source.id}: source "${source.id}" is declared but its directory is missing`);
      continue;
    }

    const declared = new Set(source.skills.map((skill) => skill.name));
    for (const entry of readdirSync(sourceRoot, { withFileTypes: true })) {
      if (!entry.isDirectory()) continue;
      if (!declared.has(entry.name)) {
        problems.push(
          `skills-ext/${source.id}/${entry.name}: not declared in scripts/skills-ext/sources.yml, so nothing records where it came from`,
        );
      }
    }

    for (const skill of source.skills) {
      const directory = skillDirectory(source, skill);
      if (!existsSync(directory)) {
        problems.push(`skills-ext/${source.id}/${skill.name}: declared but the directory is missing`);
        continue;
      }

      const present = walk(directory);
      const declaredFiles = new Set(skill.files);
      for (const file of present) {
        if (!declaredFiles.has(file)) {
          problems.push(
            `skills-ext/${source.id}/${skill.name}/${file}: ships but is not in its \`files\` list, so nothing records where it came from`,
          );
        }
      }

      for (const [file, expected] of Object.entries(skill.hashes ?? {})) {
        const actual = hashFile(join(directory, ...file.split("/")));
        if (actual === undefined) {
          problems.push(`skills-ext/${source.id}/${skill.name}/${file}: recorded but missing on disk`);
          continue;
        }
        if (actual !== expected) {
          problems.push(
            `skills-ext/${source.id}/${skill.name}/${file}: content differs from the pin. A vendored file is a copy of upstream text and must not be edited in place. Decide which change you want: to adopt a newer upstream revision, raise \`revision\` in scripts/skills-ext/sources.yml and run \`--write\`; to keep a local change, it has to be a separate file beside the vendored one rather than an edit to it`,
          );
        }
      }

      const recorded = skill.hashes ?? {};
      for (const file of skill.files) {
        if (recorded[file] === undefined && existsSync(join(directory, ...file.split("/")))) {
          problems.push(
            `skills-ext/${source.id}/${skill.name}/${file}: no recorded hash, so an edit here would go unnoticed; run \`node scripts/sync-skills-ext.ts --write\``,
          );
        }
      }
    }
  }

  return problems;
}

/**
 * Fetch every skill of one source at its pinned revision and compare.
 *
 * The network half of the check. It returns the files whose upstream content no
 * longer matches the vendored copy, which is a review decision rather than an error:
 * upstream improving a skill is not a defect in this package.
 */
export async function checkRemote(
  source: VendoredSource,
  fetchText: (url: string) => Promise<string | undefined>,
): Promise<readonly string[]> {
  const problems: string[] = [];

  for (const skill of source.skills) {
    const directory = skillDirectory(source, skill);
    for (const file of skill.files) {
      const upstreamPath = `${skill.upstream}/${file}`;
      const url = `${source.repository.replace(/\/$/, "")}/raw/${source.revision}/${upstreamPath}`;
      const remote = await fetchText(url);
      if (remote === undefined) {
        problems.push(`${source.id}/${skill.name}/${file}: upstream ${upstreamPath} is gone at ${source.revision.slice(0, 7)}`);
        continue;
      }
      const local = existsSync(join(directory, ...file.split("/")))
        ? readFileSync(join(directory, ...file.split("/")), "utf8")
        : undefined;
      if (local === undefined) {
        problems.push(`${source.id}/${skill.name}/${file}: missing locally`);
        continue;
      }
      if (local !== remote) {
        problems.push(`${source.id}/${skill.name}/${file}: differs from upstream at ${source.revision.slice(0, 7)}`);
      }
    }
  }

  return problems;
}

/** Record the current tree's hashes into the manifest. */
export function writeHashes(sources: SourcesFile): SourcesFile {
  return {
    sources: sources.sources.map((source) => ({
      ...source,
      skills: source.skills.map((skill) => ({ ...skill, hashes: hashSkill(source, skill) })),
    })),
  };
}

/** Serialize the manifest in a stable, reviewable order. */
export function renderSources(sources: SourcesFile): string {
  return yaml.dump(sources, { lineWidth: 100, noRefs: true, sortKeys: false });
}

async function fetchText(url: string): Promise<string | undefined> {
  const response = await fetch(url, { headers: { "user-agent": "dsh-pstack-skills-sync" } });
  if (response.status === 404) return undefined;
  if (!response.ok) throw new Error(`${url}: HTTP ${response.status}`);
  return response.text();
}

export async function main(argv: readonly string[] = process.argv.slice(2)): Promise<number> {
  const write = argv.includes("--write");
  const remote = argv.includes("--remote");

  let sources: SourcesFile;
  try {
    sources = readSources();
  } catch (error) {
    console.error(`skills-ext: ${error instanceof Error ? error.message : String(error)}`);
    return 1;
  }

  if (write) {
    writeFileSync(SOURCES_PATH, renderSources(writeHashes(sources)));
    console.log(`updated hashes in ${relative(ROOT, SOURCES_PATH)}`);
    return 0;
  }

  const problems = [...checkLocalTree(sources)];
  const skills = sources.sources.reduce((total, source) => total + source.skills.length, 0);
  console.log(
    `skills-ext: ${sources.sources.length} source(s), ${skills} skill(s) (${sources.sources.map((source) => `${source.id}@${source.revision.slice(0, 7)}`).join(", ")})`,
  );

  if (remote) {
    for (const source of sources.sources) {
      const drift = await checkRemote(source, fetchText);
      if (drift.length === 0) {
        console.log(`  ${source.id}: matches upstream at ${source.revision.slice(0, 7)}`);
        continue;
      }
      console.log(`  ${source.id}: ${drift.length} file(s) differ from upstream at ${source.revision.slice(0, 7)}`);
      for (const item of drift) console.log(`    ${item}`);
      console.log(`    This is upstream moving, not a defect here. To adopt it, raise \`revision\` and run --write.`);
    }
  }

  if (problems.length === 0) {
    console.log("skills-ext check passed");
    return 0;
  }
  console.error(`skills-ext check failed (${problems.length} problem(s)):`);
  for (const problem of problems) console.error(`  ${problem}`);
  return 1;
}

function walk(directory: string): readonly string[] {
  return readdirSync(directory, { withFileTypes: true })
    .flatMap((entry) => {
      const path = join(directory, entry.name);
      return entry.isDirectory() ? walk(path) : [path];
    })
    .map((path) => relative(directory, path).split("\\").join("/"))
    .sort();
}

const entryPoint = process.argv[1];
if (entryPoint !== undefined && entryPoint.endsWith("sync-skills-ext.ts")) {
  process.exitCode = await main();
}

export { statSync };
